import type { ButtonHTMLAttributes, ReactNode, Ref } from "react";
import { cx, flag } from "../utils/cx";
import { Slot } from "../utils/slot";

export type ButtonVariant = "primary" | "secondary" | "ghost" | "danger";
export type ButtonSize = "sm" | "md" | "lg";

export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  /**
   * `primary`: the one white action on a view. `secondary`: a hairline pill for tools. `ghost`: text that underlines
   * on hover (row actions). `danger`: destructive, quiet until hovered.
   */
  variant?: ButtonVariant;
  size?: ButtonSize;
  shape?: "rounded" | "pill";
  /** Shows a spinner, sets aria-busy, and blocks clicks while keeping focus. */
  loading?: boolean;
  /** Render a link (or router link) with button styling. */
  asChild?: boolean;
  ref?: Ref<HTMLButtonElement>;
  children?: ReactNode;
};

/** Server-compatible button. One quiet primary per view; everything else recedes. */
export function Button({
  variant = "primary",
  size = "md",
  shape = "rounded",
  loading,
  asChild,
  className,
  type,
  disabled,
  onClick,
  children,
  ...rest
}: ButtonProps) {
  const cls = cx("hm-button", className);
  const attrs = {
    "data-variant": variant,
    "data-size": size,
    "data-shape": shape,
    "data-loading": flag(loading),
    "aria-busy": loading || undefined,
  };
  if (asChild) {
    return (
      <Slot {...(rest as object)} {...attrs} className={cls}>
        {children}
      </Slot>
    );
  }
  return (
    <button
      {...rest}
      {...attrs}
      // while loading: no handler and no submit (so no double submits), but still focusable; no closures here, so the
      // component stays usable from a React Server Component
      type={loading ? "button" : (type ?? "button")}
      className={cls}
      disabled={disabled}
      aria-disabled={loading || undefined}
      onClick={loading ? undefined : onClick}
    >
      {loading ? <span className="hm-spinner" data-size="sm" aria-hidden="true" /> : null}
      {children}
    </button>
  );
}

export type IconButtonProps = Omit<ButtonProps, "shape" | "children"> & {
  /** Required: an icon button has no visible text. */
  "aria-label": string;
  children: ReactNode;
};

/** A square button holding a single icon. */
export function IconButton({ className, variant = "secondary", ...rest }: IconButtonProps) {
  return <Button {...rest} variant={variant} className={cx("hm-icon-button", className)} />;
}
